---@class ARUserAgreementView : ViewBase
ARUserAgreementView = class("ARUserAgreementView", ViewBase)

function ARUserAgreementView:initialize()
    ViewBase.initialize(self)
    ViewBase.RegisteAction(self, "ARUserAgreementViewAction")
    print("---   ARCarMainView 初始化完成")
end

function ARUserAgreementView:Awake()
    CommonHelper:SetNewLineText("###DesTex",self.gameObject,CommonHelper:GetTempStr_Default(TemplateStringID.ARUserAgreementContent))
    CommonHelper:HButtonSetCallback("BtnBack", self.gameObject, function(data)
        UIManager:Get():ClosePopup()
    end)
    CommonHelper:HButtonSetCallback("BtnClose", self.gameObject, function(data)
        UIManager:Get():ClosePopup()
    end)

    self.Toggle= CommonHelper:HButtonSetCallback("Toggle", self.gameObject, function(data)
        self.isAgreement = not self.isAgreement
        self:UpdateBtn()
    end)

    self.BtnEnter = CommonHelper:HButtonSetCallback("BtnEnter", self.gameObject, function(data)
        UIManager:Get():ClosePopup()
        PlayerPrefsHelper:SetValue_ArUserAgreement()
        HomeSceneHelper:SetARScene()
        ARManager:Get():AREnter()
        UIManager:Get():OpenView("ARMainView", CanvasType.MainCanvas, "ARMainView")
    end)

end

function ARUserAgreementView:OnOpen()
    self.isAgreement = false
    self:UpdateBtn()
end


function ARUserAgreementView:ReOpen()
    self.isAgreement = false
    self:UpdateBtn()
end

function ARUserAgreementView:UpdateBtn()
    CommonHelper:CSGameObjectSetActive(self.BtnEnter.gameObject,self.isAgreement)
    CommonHelper:SetGameObjectActive("Checkmark",self.Toggle.gameObject,self.isAgreement)
end